using DadoRetail.Application.Security;using DadoRetail.Domain.Identity;using DadoRetail.Domain.Organization;using DadoRetail.Infrastructure.Persistence;using Microsoft.AspNetCore.Identity;using Microsoft.EntityFrameworkCore;namespace DadoRetail.Api.Bootstrap;public static class PilotBootstrapper{public static async Task SeedAsync(IServiceProvider services,IConfiguration config,CancellationToken ct=default){if(!config.GetValue<bool>("Pilot:BootstrapEnabled"))return;using var scope=services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<DadoRetailDbContext>();await db.Database.MigrateAsync(ct);var allPermissions=new[]{Permissions.ProductView,Permissions.ProductCreate,Permissions.ProductEdit,Permissions.PurchaseCreate,Permissions.PurchasePost,Permissions.SaleCreate,Permissions.SaleRefund,Permissions.InventoryCreate,Permissions.InventoryApprove,Permissions.PriceEdit,Permissions.ReportView,Permissions.UserManage,Permissions.FiscalSale,Permissions.FiscalRetry};var role=await db.Roles.Include(x=>x.Permissions).FirstOrDefaultAsync(x=>x.Name=="PilotAdmin",ct);if(role is null){role=new Role("PilotAdmin");db.Roles.Add(role);}foreach(var code in allPermissions){var permission=await db.Permissions.FirstOrDefaultAsync(x=>x.Code==code,ct);if(permission is null){permission=new Permission(code);db.Permissions.Add(permission);}if(!role.Permissions.Any(x=>x.PermissionId==permission.Id))role.Permissions.Add(new RolePermission{Role=role,Permission=permission});}var username=config["Pilot:AdminUsername"]?.Trim().ToLowerInvariant();var password=config["Pilot:AdminPassword"];if(string.IsNullOrWhiteSpace(username)||string.IsNullOrWhiteSpace(password)||password.Length<12)throw new InvalidOperationException("Pilot bootstrap requires AdminUsername and AdminPassword (minimum 12 characters).");var user=await db.Users.Include(x=>x.Roles).FirstOrDefaultAsync(x=>x.Username==username,ct);if(user is null){var temp=new User(username,"pending");var hash=new PasswordHasher<User>().HashPassword(temp,password);user=new User(username,hash);db.Users.Add(user);}if(!user.Roles.Any(x=>x.RoleId==role.Id))user.Roles.Add(new UserRole{User=user,Role=role});var store=await db.Stores.FirstOrDefaultAsync(x=>x.Code=="DADO-01",ct);if(store is null){store=new Store("DADO-01","ДАДО — Pilot");db.Stores.Add(store);await db.SaveChangesAsync(ct);}var warehouse=await db.Warehouses.FirstOrDefaultAsync(x=>x.StoreId==store.Id&&x.Code=="MAIN",ct);if(warehouse is null)db.Warehouses.Add(new Warehouse(store.Id,"MAIN","Основной склад"));var register=await db.CashRegisters.FirstOrDefaultAsync(x=>x.StoreId==store.Id&&x.Code=="POS-01",ct);if(register is null)db.CashRegisters.Add(new CashRegister(store.Id,"POS-01"));await db.SaveChangesAsync(ct);}}
